PigeonInternalCodecSerializer::PigeonInternalCodecSerializer() {}

EncodableValue PigeonInternalCodecSerializer::ReadValueOfType(
  uint8_t type,
  ::flutter::ByteStreamReader* stream) const {
  switch (type) {
    case 129: {
        const auto& encodable_enum_arg = ReadValue(stream);
        const int64_t enum_arg_value = encodable_enum_arg.IsNull() ? 0 : encodable_enum_arg.LongValue();
        return encodable_enum_arg.IsNull() ? EncodableValue() : CustomEncodableValue(static_cast<PageEventKind>(enum_arg_value));
      }
    case 130: {
        const auto& encodable_enum_arg = ReadValue(stream);
        const int64_t enum_arg_value = encodable_enum_arg.IsNull() ? 0 : encodable_enum_arg.LongValue();
        return encodable_enum_arg.IsNull() ? EncodableValue() : CustomEncodableValue(static_cast<FocusDirection>(enum_arg_value));
      }
    case 131: {
        const auto& encodable_enum_arg = ReadValue(stream);
        const int64_t enum_arg_value = encodable_enum_arg.IsNull() ? 0 : encodable_enum_arg.LongValue();
        return encodable_enum_arg.IsNull() ? EncodableValue() : CustomEncodableValue(static_cast<DialogKind>(enum_arg_value));
      }
    case 132: {
        return CustomEncodableValue(PageEvent::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 133: {
        return CustomEncodableValue(PageCookie::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 134: {
        return CustomEncodableValue(PageCapabilities::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 135: {
        return CustomEncodableValue(PageFrame::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    default:
      return ::flutter::StandardCodecSerializer::ReadValueOfType(type, stream);
    }
}

void PigeonInternalCodecSerializer::WriteValue(
  const EncodableValue& value,
  ::flutter::ByteStreamWriter* stream) const {
  if (const CustomEncodableValue* custom_value = std::get_if<CustomEncodableValue>(&value)) {
    if (custom_value->type() == typeid(PageEventKind)) {
      stream->WriteByte(129);
      WriteValue(EncodableValue(static_cast<int>(std::any_cast<PageEventKind>(*custom_value))), stream);
      return;
    }
    if (custom_value->type() == typeid(FocusDirection)) {
      stream->WriteByte(130);
      WriteValue(EncodableValue(static_cast<int>(std::any_cast<FocusDirection>(*custom_value))), stream);
      return;
    }
    if (custom_value->type() == typeid(DialogKind)) {
      stream->WriteByte(131);
      WriteValue(EncodableValue(static_cast<int>(std::any_cast<DialogKind>(*custom_value))), stream);
      return;
    }
    if (custom_value->type() == typeid(PageEvent)) {
      stream->WriteByte(132);
      WriteValue(EncodableValue(std::any_cast<PageEvent>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(PageCookie)) {
      stream->WriteByte(133);
      WriteValue(EncodableValue(std::any_cast<PageCookie>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(PageCapabilities)) {
      stream->WriteByte(134);
      WriteValue(EncodableValue(std::any_cast<PageCapabilities>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(PageFrame)) {
      stream->WriteByte(135);
      WriteValue(EncodableValue(std::any_cast<PageFrame>(*custom_value).ToEncodableList()), stream);
      return;
    }
  }
  ::flutter::StandardCodecSerializer::WriteValue(value, stream);
}

